import bisect

class SORTracker:
    def __init__(self):
        self.locations = []
        self.query_index = 0

    def add(self, name: str, score: int) -> None:
        key = (-score, name)
        bisect.insort(self.locations, key)

    def get(self) -> str:
        name = self.locations[self.query_index][1]
        self.query_index += 1
        return name

#include <string>
#include <set>

class SORTracker {
    struct Item {
        int score;
        std::string name;
        bool operator<(const Item& other) const {
            if (score != other.score) return score > other.score;
            return name < other.name;
        }
    };

    std::set<Item> items;
    std::set<Item>::iterator cursor;

public:
    SORTracker() {
        cursor = items.end();
    }

    void add(std::string name, int score) {
        Item itm = {score, name};
        auto it = items.insert(itm).first;
        if (cursor == items.end() || *it < *cursor) {
            if (cursor != items.end()) cursor--;
        }
    }

    std::string get() {
        if (cursor == items.end()) cursor = items.begin();
        else cursor++;
        return cursor->name;
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class SORTracker {
    static class Item implements Comparable<Item> {
        int score;
        String name;

        Item(String name, int score) {
            this.name = name;
            this.score = score;
        }

        @Override
        public int compareTo(Item o) {
            if (this.score != o.score) {
                return Integer.compare(o.score, this.score);
            }
            return this.name.compareTo(o.name);
        }
    }

    private final List<Item> list = new ArrayList<>();
    private int cursor = 0;

    public SORTracker() {}

    public void add(String name, int score) {
        Item item = new Item(name, score);
        int idx = Collections.binarySearch(list, item);
        if (idx < 0) idx = -(idx + 1);
        list.add(idx, item);
    }

    public String get() {
        String res = list.get(cursor).name;
        cursor++;
        return res;
    }
}

var SORTracker = function() {
    this.locations = [];
    this.cursor = 0;
};

/** 
 * @param {string} name 
 * @param {number} score
 * @return {void}
 */
SORTracker.prototype.add = function(name, score) {
    let low = 0, high = this.locations.length;
    while (low < high) {
        const mid = (low + high) >> 1;
        const other = this.locations[mid];
        let cmp = other.score - score;
        if (cmp === 0) cmp = name < other.name ? -1 : 1;
        if (cmp > 0) low = mid + 1;
        else high = mid;
    }
    this.locations.splice(low, 0, { name, score });
};

/**
 * @return {string}
 */
SORTracker.prototype.get = function() {
    const res = this.locations[this.cursor].name;
    this.cursor++;
    return res;
};
